input.script:
# First, list all orders for March 2026
page1 = list_orders({ month: "2026-03", page: 1 })

# Fetch all remaining pages in parallel
remaining_pages = for page in list.range(2, page1.total_pages + 1) {
    result = list_orders({ month: "2026-03", page })
    return result.items
}

# Combine all items
all_items = fold acc = page1.items for page in remaining_pages {
    return acc + page
}

# For each order, get order details (status, amount) and customer (region)
enriched = for item in all_items {
    order = get_order({ id: item.id })
    # skip non-completed
    skip if order.status != "completed"
    customer = get_customer({ id: item.customer_id })
    return {
        amount: order.amount_cents,
        region: customer.region
    }
}

# Sum by region
na_total = fold acc = 0 for e in enriched {
    return acc + e.amount if e.region == "NA" else acc
}
eu_total = fold acc = 0 for e in enriched {
    return acc + e.amount if e.region == "EU" else acc
}
apac_total = fold acc = 0 for e in enriched {
    return acc + e.amount if e.region == "APAC" else acc
}

return { NA: na_total, EU: eu_total, APAC: apac_total }
